content.FloodZoneUpdated:
@if(
  empty(string(item()?['Flood Zone Updated'])),
  null,
  if(
    isInt(string(item()?['Flood Zone Updated'])),
    formatDateTime(
      addDays(
        '1899-12-30', 
        int(item()?['Flood Zone Updated'])
      ),
      'yyyy-MM-dd'
    ),
    if(
      contains(
        item()?['Flood Zone Updated'],
        '/'
      ),
      formatDateTime(
        item()?['Flood Zone Updated'],
        'yyyy-MM-dd'
      ),
      if(
        and(
          contains(
            item()?['Flood Zone Updated'],
            '-'
          ),
          equals(
            length(item()?['Flood Zone Updated']),
            10
          )
        ),
        item()?['Flood Zone Updated'],
        null
      )
    )
  )
)

