content.RadarID:
@{if(
  or(
    not(empty(string(item()?['Parcel Number']))),
    not(empty(string(item()?['PropertyID'])))
  ),
  concat(
    if(
      not(empty(string(item()?['PropertyID']))),
      item()?['PropertyID'],
      item()?['Parcel Number']
    ),
    '-',
    if(
      not(empty(string(item()?['Zip']))),
      item()?['Zip'],
      if(
        not(empty(string(item()?['State']))),
        item()?['State'],
        triggerBody()?['State/Value']
      )
    )
  ),
  if(
    not(empty(string(item()?['PREFORECLOSURETYPE']))),
    concat(
      if(
        not(empty(string(item()?['Latitude']))),
        item()?['Latitude'],
        concat(
          item()?['DOCUMENTNUM'],
          '-'
        )
      ),
      if(
        not(empty(string(item()?['Longitude']))),
        item()?['Longitude'],
        if(
          not(empty(string(item()?['DOCUMENTNUM']))),
          if(
            not(empty(string(item()?['Zip']))),
            item()?['Zip'],
            if(
              not(empty(string(item()?['State']))),
              item()?['State'],
              triggerBody()?['State/Value']
            )
          ),
          ''
        )
      )
    ),
    concat(
      if(
        equals(
          string(item()?['Tax ID']),
          '0'
        ),
        concat(
          item()?['County Code'],
          '-',
          trim(
            replace(
              item()?['Volume'],
              '`',
              ''
            )    
          )
        ),
        item()?['Tax ID']
      ),
      '-',
      item()?['Loan Year'],
      '-',
      item()?['Loan Month']
    )
  )
)}

