      not(contains(string(item()?['Auction Date']), '/')),
      not(contains(string(item()?['Auction Date']), '-'))
    )
  ),
  if(
    not(empty(string(triggerBody()?['SaleDate']))),
    triggerBody()?['SaleDate'],
    if(
      and(
        not(empty(string(item()?['AUCTIONDATETIME']))),
        equals(
          length(trim(string(item()?['AUCTIONDATETIME']))),
          18
        )
      ),
      formatDateTime(
        substring(item()?['AUCTIONDATETIME'], 0, 10),
        'yyyy-MM-dd'
      ),
      null
    )
  ),
  if(
    isInt(string(item()?['Auction Date'])),
    formatDateTime(
      addDays(
        '1899-12-30', 
        int(item()?['Auction Date'])
      ),
      'yyyy-MM-dd'
    ),
    if(
      contains(
        item()?['Auction Date'],
