inputs.where:
@equals(and(
  not(
    empty(
      string(
          outputs('Update_Payload')?
          [
            item()?['API Key']
          ]
      )
    )
  ),
  not(
    equals(
      toLower(
        string(
          first(body('Find_Matching_Item')?['value'])?
            [
              if(
                equals(
                  item()?['SPL Type'],
                  'Choice'
                ),
                concat(
                  item()?['SPL Column'],
                  '/Value'
                ),
                item()?['SPL Column']
              )
            ]
        )
      ),
      toLower(
        string(
          outputs('Update_Payload')?
          [
            item()?['API Key']
          ]
        )
      )
    )
  )
),true)

select.@{item()?['API Key']}:
@concat(
  string(
    first(body('Find_Matching_Item')?['value'])?
      [
        if(
          equals(
            item()?['SPL Type'],
            'Choice'
          ),
          concat(
            item()?['SPL Column'],
            '/Value'
          ),
          item()?['SPL Column']
        )
      ]
  ),
  ' <> ',
  string(
    outputs('Update_Payload')?
    [
      item()?['API Key']
    ]
  )
)

Alternate_UID.inputs:
@if(
  and(
    lessOrEquals(
      length(body('Transform_Data')?['RadarID']),
      9
    ),
    contains(
      body('Transform_Data')?['RadarID'],
      '-0-0-0'
    )
  ),
  if(
    not(empty(string(body('Transform_Data')?['Latitude']))),
    concat(
      body('Transform_Data')?['Latitude'],
      body('Transform_Data')?['Longitude']
    ),
    body('Transform_Data')?['RadarID']
  ),
  body('Transform_Data')?['RadarID']
)

select.SPL Column:
@trim(
  replace(
    replace(
      last(
        split(
          replace(
            xpath(item(), 'string(/Item/AVPProperty/Value)'), 
            '_x005F_x', '_x'
          ),
          'ID: '
        )
      ),
      ')',
      ''
    ),
    '/Value',
    ''
  )
)

select.SPL Type:
@trim(
  first(
    split(
      last(
        split(
          replace(
            xpath(item(), 'string(/Item/AVPProperty/Value)'), 
            '_x005F_x', '_x'
          ),
          'Data: '
        )
      ),
      ', '
    )
  )
)
